import collections
import json
import math
from pathlib import Path
import re
import statistics

ROOT = Path('/home/niteris/dev/obs-rust/obs-studio2/build_ci_audit')

def summarize(records):
    passing = [r for r in records if r['conclusion'] == 'success' and r['gate_seconds'] is not None]
    values = sorted(r['gate_seconds'] for r in passing)
    return {
        'runs': len(records), 'successful_gates': len(values),
        'median_gate_seconds': statistics.median(values) if values else None,
        'p95_gate_seconds': values[math.ceil(.95 * len(values)) - 1] if values else None,
        'median_successful_runner_minutes': statistics.median(r['runner_minutes'] for r in passing) if passing else None,
        'outcomes': {outcome: {'runs': len(rr), 'runner_minutes': round(sum(r['runner_minutes'] for r in rr), 3)}
                     for outcome in sorted({r['conclusion'] for r in records})
                     for rr in [[r for r in records if r['conclusion'] == outcome]]},
        'run_ids': [r['databaseId'] for r in records],
    }

def signature(record):
    names = set()
    for job in record['jobs']:
        if job['conclusion'] == 'skipped' or '${{' in job['name']:
            continue
        name = re.sub(r', shard [12]/2', '', job['name'])
        names.add(name)
    return tuple(sorted(names))

days = {}
for side in ('before', 'after'):
    records = [json.loads(p.read_text()) for p in sorted((ROOT / f'1581-{side}-full').glob('run-*.json'))]
    buckets = collections.defaultdict(list)
    for record in records:
        if record['cohort'] == 'code' and record['event'] in ('pull_request', 'merge_group'):
            buckets[(record['event'], signature(record))].append(record)
    days[side] = (records, buckets)

groups = []
for key in sorted(set(days['before'][1]) & set(days['after'][1])):
    before, after = (days[side][1][key] for side in ('before', 'after'))
    if not any(r['conclusion'] == 'success' for r in before) or not any(r['conclusion'] == 'success' for r in after):
        continue
    groups.append({'event': key[0], 'selected_job_names': key[1],
                   **{side: summarize(rr) for side, rr in [('before', before), ('after', after)]},
                   'first_attempt_only': {side: summarize([r for r in rr if r['run_attempt'] == 1])
                                          for side, rr in [('before', before), ('after', after)]}})
result = {'method': 'Exact non-skipped job-name set, normalizing shard suffix only. Code cohort only. Nearest-rank p95. Latest attempts; first-attempt sensitivity included. Not causal: source, cache and runner revisions differ.',
          'matched_groups': groups,
          'broad_code': {side: {event: summarize([r for r in days[side][0] if r['event'] == event and r['cohort'] == 'code'])
                                for event in ('pull_request', 'merge_group')} for side in days}}
output = ROOT / '1581-day-comparison.json'
output.write_text(json.dumps(result, indent=2) + '\n')
for group in groups:
    print(group['event'], group['before']['successful_gates'], group['after']['successful_gates'],
          group['before']['median_gate_seconds'], group['after']['median_gate_seconds'],
          [n for n in group['selected_job_names'] if 'Build' in n])

